"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.
"""

from __future__ import annotations

import ast
import operator
from typing import Any

from plugins import BUILTIN_PLUGINS

# Profile text is tenant-controlled, so values are evaluated with a whitelist AST
# interpreter instead of eval(): only constants, containers, arithmetic, and
# comprehensions over those are allowed. Calls, attribute access, and names from this
# process are never available, so a profile cannot execute code on the loader's host.
# The caps below bound how much a single expression may allocate (e.g. ``2 ** 10**9``
# or ``"A" * 10**9`` would otherwise exhaust memory).
_MAX_DEPTH = 100  # expression nesting depth
_MAX_ITEMS = 100_000  # items/chars a container, repetition, or comprehension may build
_MAX_EXPONENT = 1_024  # magnitude bound for ``**`` exponents

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
    ast.Not: operator.not_,
}


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).

    Values may use Python literal syntax (numbers, strings, lists, dicts, ...), arithmetic
    (``8 * 1024``), and comprehensions over literals — evaluated by a whitelist
    interpreter, never ``eval``, because profiles are tenant-supplied. ``plugin`` must be
    a string matching an entry in ``plugins.BUILTIN_PLUGINS``: a profile can only select
    an already-installed plugin, it cannot name arbitrary modules to import.

    Raises ``ValueError`` for malformed lines, disallowed expressions, or unknown plugins.
    """
    settings: dict[str, Any] = {}
    plugin_name: str | None = None

    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, raw_value = line.partition("=")
        key = key.strip()
        if not sep or not key:
            raise ValueError(f"line {lineno}: expected 'key = value', got {raw!r}")
        try:
            value = _eval_value(raw_value.strip())
        except (SyntaxError, ValueError, TypeError, ArithmeticError,
                RecursionError, MemoryError) as exc:
            raise ValueError(f"line {lineno}: invalid value for {key!r}: {exc}") from exc
        if key == "plugin":
            if not isinstance(value, str):
                raise ValueError(
                    f"line {lineno}: 'plugin' must be a plugin name string, got {value!r}"
                )
            plugin_name = value
        else:
            settings[key] = value

    plugin = None
    if plugin_name is not None:
        try:
            plugin_cls = BUILTIN_PLUGINS[plugin_name]
        except KeyError:
            known = ", ".join(sorted(BUILTIN_PLUGINS))
            raise ValueError(
                f"unknown plugin {plugin_name!r}; available plugins: {known}"
            ) from None
        plugin = plugin_cls()

    return {"settings": settings, "plugin": plugin}


def _eval_value(expr: str) -> Any:
    """Evaluate one profile value with the whitelist AST interpreter (never ``eval``)."""
    tree = ast.parse(expr, mode="eval")
    return _eval_node(tree.body, {}, 0)


def _eval_node(node: ast.AST, scope: dict[str, Any], depth: int) -> Any:
    if depth > _MAX_DEPTH:
        raise ValueError(f"expression nested deeper than {_MAX_DEPTH} levels")
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.List):
        return _capped([_eval_node(elt, scope, depth + 1) for elt in node.elts])
    if isinstance(node, ast.Tuple):
        return _capped(tuple(_eval_node(elt, scope, depth + 1) for elt in node.elts))
    if isinstance(node, ast.Set):
        return _capped({_eval_node(elt, scope, depth + 1) for elt in node.elts})
    if isinstance(node, ast.Dict):
        return _capped({
            _eval_node(key, scope, depth + 1): _eval_node(val, scope, depth + 1)
            for key, val in zip(node.keys, node.values)
        })
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPS:
        return _UNARY_OPS[type(node.op)](_eval_node(node.operand, scope, depth + 1))
    if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
        return _eval_binop(node, scope, depth)
    if isinstance(node, ast.Name):
        if node.id in scope:  # only comprehension variables are ever in scope
            return scope[node.id]
        raise ValueError(f"name {node.id!r} is not available in profile values")
    if isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
        return _eval_comprehension(node, scope, depth)
    raise ValueError(f"{type(node).__name__} is not allowed in profile values")


def _eval_binop(node: ast.BinOp, scope: dict[str, Any], depth: int) -> Any:
    left = _eval_node(node.left, scope, depth + 1)
    right = _eval_node(node.right, scope, depth + 1)
    if isinstance(node.op, ast.Pow):
        # ``2 ** (10**9)`` would compute an integer with ~300M digits; cap the exponent.
        if isinstance(right, (int, float)) and abs(right) > _MAX_EXPONENT:
            raise ValueError(f"exponent exceeds the {_MAX_EXPONENT} limit")
    if isinstance(node.op, ast.Mult):
        # ``"A" * 10**9`` amplification: bound before the allocation happens.
        for seq, count in ((left, right), (right, left)):
            if isinstance(seq, (str, bytes, list, tuple)) and isinstance(count, int):
                if len(seq) * count > _MAX_ITEMS:
                    raise ValueError(f"repetition exceeds the {_MAX_ITEMS}-item limit")
    return _capped(_BIN_OPS[type(node.op)](left, right))


def _eval_comprehension(node: ast.AST, scope: dict[str, Any], depth: int) -> Any:
    iterations = 0

    def scopes(gen_index: int, current: dict[str, Any]):
        nonlocal iterations
        if gen_index == len(node.generators):
            yield current
            return
        gen = node.generators[gen_index]
        if gen.is_async:
            raise ValueError("async comprehensions are not allowed in profile values")
        for item in _eval_node(gen.iter, current, depth + 1):
            iterations += 1
            if iterations > _MAX_ITEMS:
                raise ValueError(
                    f"comprehension exceeds the {_MAX_ITEMS}-iteration limit"
                )
            inner = dict(current)
            _bind_target(gen.target, item, inner)
            if all(_eval_node(cond, inner, depth + 1) for cond in gen.ifs):
                yield from scopes(gen_index + 1, inner)

    if isinstance(node, ast.DictComp):
        return _capped({
            _eval_node(node.key, env, depth + 1): _eval_node(node.value, env, depth + 1)
            for env in scopes(0, dict(scope))
        })
    results = [_eval_node(node.elt, env, depth + 1) for env in scopes(0, dict(scope))]
    if isinstance(node, ast.SetComp):
        return _capped(set(results))
    return _capped(results)  # ListComp; GeneratorExp is materialized as a list


def _bind_target(target: ast.AST, value: Any, scope: dict[str, Any]) -> None:
    """Bind a comprehension loop target (a name or tuple of names) in ``scope``."""
    if isinstance(target, ast.Name):
        scope[target.id] = value
    elif isinstance(target, (ast.Tuple, ast.List)):
        items = list(value)
        if len(items) != len(target.elts):
            raise ValueError(f"cannot unpack {len(items)} items into comprehension target")
        for elt, item in zip(target.elts, items):
            _bind_target(elt, item, scope)
    else:
        raise ValueError(
            f"{type(target).__name__} is not allowed as a comprehension target"
        )


def _capped(value: Any) -> Any:
    """Reject oversized containers/strings so one expression can't exhaust memory."""
    if isinstance(value, (str, bytes, list, tuple, set, frozenset, dict)):
        if len(value) > _MAX_ITEMS:
            raise ValueError(f"value exceeds the {_MAX_ITEMS}-item limit")
    return value

"""Tests for the safe profile-value evaluator and plugin resolution.

Profiles are tenant-supplied, so these pin both the supported expression flexibility
(arithmetic, containers, comprehensions) and the rejection of anything that would
execute code or exhaust memory on the loader's host.
"""

import unittest

from config_loader import load_config


class SafeEvalTest(unittest.TestCase):
    def test_arithmetic_values(self):
        cfg = load_config("max_size = 8 * 1024\nratio = 3 / 4\nneg = -5")
        self.assertEqual(cfg["settings"]["max_size"], 8192)
        self.assertEqual(cfg["settings"]["ratio"], 0.75)
        self.assertEqual(cfg["settings"]["neg"], -5)

    def test_nested_containers(self):
        cfg = load_config('limits = {"mem": 8 * 1024, "flags": [True, False], "x": None}')
        self.assertEqual(
            cfg["settings"]["limits"],
            {"mem": 8192, "flags": [True, False], "x": None},
        )

    def test_comprehension_over_literal(self):
        cfg = load_config("ports = [8000 + i for i in [0, 1, 2] if i > 0]")
        self.assertEqual(cfg["settings"]["ports"], [8001, 8002])

    def test_inline_comment(self):
        cfg = load_config("workers = 4  # worker processes")
        self.assertEqual(cfg["settings"]["workers"], 4)

    def test_no_plugin_defaults_to_none(self):
        self.assertIsNone(load_config("retries = 3")["plugin"])

    def test_reverse_plugin(self):
        cfg = load_config('plugin = "acme_reverse"')
        self.assertEqual(cfg["plugin"].transform("ab"), "ba")

    def test_rejects_code_execution(self):
        with self.assertRaises(ValueError):
            load_config('x = __import__("os").system("id")')

    def test_rejects_calls_and_attribute_access(self):
        for value in ('"".join(["a", "b"])', "open('/etc/passwd')", "(1).bit_length()"):
            with self.subTest(value=value), self.assertRaises(ValueError):
                load_config(f"x = {value}")

    def test_rejects_unknown_names(self):
        with self.assertRaises(ValueError):
            load_config("x = os.environ")

    def test_rejects_exponent_bomb(self):
        with self.assertRaises(ValueError):
            load_config("x = 2 ** 1000000000")

    def test_rejects_repetition_bomb(self):
        with self.assertRaises(ValueError):
            load_config('x = "A" * 10**9')

    def test_rejects_deep_nesting(self):
        with self.assertRaises(ValueError):
            load_config("x = " + "[" * 200 + "1" + "]" * 200)

    def test_unknown_plugin_rejected(self):
        with self.assertRaises(ValueError):
            load_config('plugin = "tenant_supplied_module"')

    def test_non_string_plugin_rejected(self):
        with self.assertRaises(ValueError):
            load_config("plugin = 42")

    def test_malformed_line_rejected(self):
        with self.assertRaises(ValueError):
            load_config("this line has no equals sign")


if __name__ == "__main__":
    unittest.main()

